/**
 * The ideas the curriculum teaches, which lessons teach each one, and how to spot a lesson using it.
 *
 * scripts/concept-prerequisites.ts reads the prose and exercises of every lesson (not its code, which
 * scripts/code-prerequisites.ts covers) and finds the concepts each one uses. A lesson that uses a concept must
 * require, directly or not, one of the lessons that teach it, so that Learn never hands out a lesson before the
 * ideas it builds on. The script adds the missing links to src/content/concept-prerequisites.json.
 *
 * - `taughtIn`: the lessons that teach the concept. Any one of them is enough.
 * - `patterns`: regular expressions, matched case-insensitively against the lesson's text. A pattern that starts
 *   with "=" is matched case-sensitively.
 * - `practiceOnly`: count only uses in the exercises.
 *
 * A lesson uses a concept when an exercise mentions it, or when its puzzle, intuition and theory mention it at
 * least twice. Sentences that look ahead ("later", "you will meet", "a first look") and the glimpse section do
 * not count, since naming what comes next is not using it.
 *
 * When you write a lesson that teaches a concept, add it to `taughtIn`. When a lesson names a concept in passing
 * and does not need it to be followed or answered, add it to WAIVED with the reason.
 */

export interface Concept {
  name: string;
  taughtIn: string[];
  patterns: string[];
  practiceOnly?: boolean;
}

